{
  "meta": {
    "title": "Rate limiters: what breaks first",
    "topicClass": "concept",
    "format": "full",
    "targetLengthSec": 75
  },
  "story": {
    "devices": [
      "contention_hook",
      "planted_question",
      "failure_before_fix",
      "real_incident",
      "spec_card_ending"
    ],
    "runningExample": "One checkout service sends payment calls to a provider that allows 300 requests per second.",
    "chapters": [
      {
        "id": "flood",
        "title": "The flood"
      },
      {
        "id": "counting",
        "title": "Counting requests"
      },
      {
        "id": "fleet",
        "title": "Many gateways"
      },
      {
        "id": "incident",
        "title": "The slow store"
      }
    ],
    "beats": [
      {
        "id": "hook",
        "chapterId": "flood",
        "intent": "Forty checkout instances each push their own 300 requests per second at one payment provider.",
        "device": "contention_hook",
        "targetSec": 8,
        "factIds": [
          "num-22",
          "num-24"
        ],
        "layoutMode": "centered_focus",
        "suggestedPatternIds": [
          "flood_then_funnel"
        ]
      },
      {
        "id": "fixed-window",
        "chapterId": "counting",
        "intent": "A per-minute counter resets on the hour mark and lets twice the limit through across the boundary.",
        "targetSec": 10,
        "factIds": [
          "fact-9",
          "num-6"
        ],
        "layoutMode": "versus_split",
        "suggestedPatternIds": [
          "versus_split"
        ]
      },
      {
        "id": "bucket",
        "chapterId": "counting",
        "intent": "Each request takes a token from a bucket of 100; an empty bucket answers 429.",
        "targetSec": 10,
        "factIds": [
          "fact-1",
          "fact-3",
          "fact-10",
          "num-1",
          "num-26"
        ],
        "layoutMode": "centered_focus",
        "newTerms": [
          "token bucket"
        ]
      },
      {
        "id": "refill",
        "chapterId": "counting",
        "intent": "Tokens drip back at 10 per second, computed from elapsed time, never past the cap.",
        "targetSec": 8,
        "factIds": [
          "fact-5",
          "num-2"
        ],
        "layoutMode": "centered_focus",
        "newTerms": [
          "refill rate"
        ]
      },
      {
        "id": "fleet",
        "chapterId": "fleet",
        "intent": "With a bucket on each of 24 gateways, one client gets 24 times its limit.",
        "device": "failure_before_fix",
        "targetSec": 9,
        "factIds": [
          "fact-7",
          "num-3"
        ],
        "layoutMode": "hub_spoke",
        "suggestedPatternIds": [
          "fan_out"
        ]
      },
      {
        "id": "shared",
        "chapterId": "fleet",
        "intent": "Every gateway asks one shared store, which checks and takes the token in one atomic step.",
        "targetSec": 10,
        "factIds": [
          "fact-6",
          "fact-8",
          "num-4"
        ],
        "layoutMode": "hub_spoke",
        "suggestedPatternIds": [
          "atomic_lock"
        ],
        "newTerms": [
          "shared store"
        ]
      },
      {
        "id": "incident",
        "chapterId": "incident",
        "intent": "The store fails over to another zone, calls jump to 80 ms, the limiter fails open and checkout floods the provider.",
        "device": "real_incident",
        "targetSec": 12,
        "factIds": [
          "fact-19",
          "fact-20",
          "fact-21",
          "num-18",
          "num-19",
          "num-21"
        ],
        "layoutMode": "pipeline",
        "suggestedPatternIds": [
          "failover"
        ],
        "source": "Larkspur Pay platform team, 14 March 2025"
      },
      {
        "id": "spec",
        "chapterId": "incident",
        "intent": "The design on one card: bucket per key, one shared store, fail closed in front of payments.",
        "device": "spec_card_ending",
        "targetSec": 8,
        "factIds": [
          "fact-23"
        ],
        "layoutMode": "stacked_list"
      }
    ],
    "plantedQuestion": {
      "text": "Why did forty instances send forty times the contracted rate?",
      "beatId": "hook",
      "payoffBeatId": "incident"
    },
    "rejectedAlternative": {
      "beatId": "fixed-window",
      "summary": "A fixed-window counter lets twice the limit through at the minute boundary.",
      "chosenBeatId": "bucket"
    },
    "ending": {
      "kind": "spec_card_ending",
      "cta": "Share it with whoever is on call for checkout.",
      "specCard": {
        "lines": [
          "Token bucket per key and route",
          "One shared store, atomic take",
          "Slow store: fail closed on payments"
        ]
      }
    },
    "missingPrimitiveRequests": [
      {
        "name": "token_bucket",
        "description": "A bucket that loses one token per request and refills at a steady drip up to its cap.",
        "fallbackUsed": "counter"
      }
    ]
  }
}
